package vmangos

import (
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"Meld/internal/mpq"
)

// BenchmarkInstallPatch saves one small file into a patch that already holds benchFiles tiles of
// benchSize bytes each (generated bytes, no client files), as a one-row DBC save or an imported icon
// does in a continent project (#476). Run with -benchmem: the bytes allocated a save are the measure.
func BenchmarkInstallPatch(b *testing.B) {
	const benchFiles, benchSize = 200, 512 << 10
	dir := b.TempDir()
	files := make([]mpq.File, benchFiles)
	for i := range files {
		data := make([]byte, benchSize)
		for k := range data {
			data[k] = byte(i + k)
		}
		files[i] = mpq.File{Name: fmt.Sprintf(`World\Maps\Bench\Bench_%d_%d.adt`, i/64, i%64), Data: data}
	}
	if _, err := InstallPatch(dir, files); err != nil {
		b.Fatal(err)
	}
	icon := []mpq.File{{Name: `Interface\Icons\Meld_Bench.blp`, Data: make([]byte, 4096)}}
	b.SetBytes(benchFiles * benchSize)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		icon[0].Data[0] = byte(i)
		changed, err := ChangedFiles(dir, icon)
		if err != nil {
			b.Fatal(err)
		}
		if _, err := InstallPatch(dir, changed); err != nil {
			b.Fatal(err)
		}
	}
	b.StopTimer()
	if info, err := os.Stat(filepath.Join(dir, PatchName)); err != nil || info.Size() < benchFiles*benchSize {
		b.Fatalf("patch is %v, %v", info, err)
	}
}
